import { SortableList, type SortableListChangeDetail, type SortableListItem } from '@absoluteui/components/sortable-list';

const host = document.querySelector<HTMLElement>('#priorities');
if (host) {
  const list = SortableList.create(host, {
    label: 'Priorities',
    items: [
      { id: 'security', label: 'Security review' },
      { id: 'performance', label: 'Performance' },
      { id: 'docs', label: 'Documentation' },
    ],
  });
  host.addEventListener('aui-change', (event) => {
    const { order } = (event as CustomEvent<SortableListChangeDetail>).detail;
    const byId = new Map(list.options.items.map((item): [string, SortableListItem] => [item.id, item]));
    // Feed the new order back so later updates and config changes keep it.
    list.update({ items: order.flatMap((id) => byId.get(id) ?? []) });
    // persist `order` here
  });
}

import { SortableList, type SortableListItem } from '@absoluteui/components/sortable-list';

const card = (title: string, owner: string): HTMLElement => {
  const el = document.createElement('div');
  const strong = document.createElement('strong');
  strong.textContent = title;
  el.append(strong, ` - ${owner}`);
  return el;
};
const items: SortableListItem[] = [
  { id: 'notes', label: 'Release notes', content: card('Release notes', 'Ana'), disabled: true },
  { id: 'api', label: 'API review', content: card('API review', 'Ben') },
  { id: 'qa', label: 'QA pass', content: card('QA pass', 'Chen') },
];
const host = document.createElement('div');
document.body.append(host);
SortableList.create(host, { label: 'Backlog', items, dragFrom: 'item' });

import { SortableList } from '@absoluteui/components/sortable-list';

const host = document.createElement('div');
document.body.append(host);
const tracks = SortableList.create(host, {
  label: 'Playlist',
  items: [
    { id: 't1', label: 'Intro' },
    { id: 't2', label: 'Theme' },
    { id: 't3', label: 'Finale' },
  ],
});
document.querySelector('#finale-first')?.addEventListener('click', () => {
  if (!tracks.isDragging) tracks.move('t3', 0);
  const order: string[] = tracks.order;
  host.dataset.order = order.join(',');
});
